    "type": "object",
    "additionalProperties": false,
    "required": [
     "chu_id",
     "kieu",
     "ten"
    ],
    "properties": {
     "chu_id": {
      "type": "string"
     },
     "kieu": {
      "type": "string",
      "enum": [
       "reuse",
       "new"
      ]
     },
